  "Omni video": "Omni ವೀಡಿಯೊ",
  "On": "ಆನ್",
  "On YouTube": "YouTube ನಲ್ಲಿ",
  "On-screen dialogue · {lang}": "ಪರದೆಯ ಮೇಲಿನ ಸಂಭಾಷಣೆ · {lang}",
  "One rule per line. e.g. Say “devotees”, never “customers”.": "ಪ್ರತಿ ಸಾಲಿಗೆ ಒಂದು ನಿಯಮ. ಉದಾ. “ಭಕ್ತರು” ಎನ್ನಿ, “ಗ್ರಾಹಕರು” ಎಂದು ಎಂದಿಗೂ ಬೇಡ.",
  "Only add what you want to change. Overrides merge one level deep, so give every resolution for a video model you change.": "ನೀವು ಬದಲಾಯಿಸಲು ಬಯಸುವುದನ್ನು ಮಾತ್ರ ಸೇರಿಸಿ. ಓವರ್‌ರೈಡ್‌ಗಳು ಒಂದು ಹಂತದ ಆಳದವರೆಗೆ ಮಾತ್ರ ವಿಲೀನಗೊಳ್ಳುತ್ತವೆ, ಆದ್ದರಿಂದ ನೀವು ಬದಲಾಯಿಸುವ ವೀಡಿಯೊ ಮಾಡೆಲ್‌ಗೆ ಎಲ್ಲಾ ರೆಸಲ್ಯೂಶನ್‌ಗಳನ್ನು ನೀಡಿ.",
  "Only admins can add people, change roles or set spending limits. Ask an admin if something needs to change.": "ನಿರ್ವಾಹಕರು ಮಾತ್ರ ಜನರನ್ನು ಸೇರಿಸಬಹುದು, ರೋಲ್‌ಗಳನ್ನು ಬದಲಾಯಿಸಬಹುದು ಅಥವಾ ಖರ್ಚಿನ ಮಿತಿಗಳನ್ನು ಹೊಂದಿಸಬಹುದು. ಏನಾದರೂ ಬದಲಾಗಬೇಕಿದ್ದರೆ ನಿರ್ವಾಹಕರನ್ನು ಕೇಳಿ.",
  "Only admins can change routing": "ನಿರ್ವಾಹಕರು ಮಾತ್ರ ರೂಟಿಂಗ್ ಬದಲಾಯಿಸಬಹುದು",
  "Only admins can change these.": "ನಿರ್ವಾಹಕರು ಮಾತ್ರ ಇವುಗಳನ್ನು ಬದಲಾಯಿಸಬಹುದು.",
  "Only admins can switch engines on or off": "ನಿರ್ವಾಹಕರು ಮಾತ್ರ ಎಂಜಿನ್‌ಗಳನ್ನು ಆನ್ ಅಥವಾ ಆಫ್ ಮಾಡಬಹುದು",
  "Only change these if a model is renamed or a price changes. Wrong values can break generation.": "ಮಾಡೆಲ್ ಹೆಸರು ಬದಲಾದರೆ ಅಥವಾ ಬೆಲೆ ಬದಲಾದರೆ ಮಾತ್ರ ಇವುಗಳನ್ನು ಬದಲಾಯಿಸಿ. ತಪ್ಪು ಮೌಲ್ಯಗಳು ರಚನೆಯನ್ನು ಹಾಳುಮಾಡಬಹುದು.",
  "Only final renders can be approved": "ಅಂತಿಮ ರೆಂಡರ್‌ಗಳನ್ನು ಮಾತ್ರ ಅನುಮೋದಿಸಬಹುದು",
  "Only one language in this project. Add languages in the Brief to dub.": "ಈ ಪ್ರಾಜೆಕ್ಟ್‌ನಲ್ಲಿ ಒಂದೇ ಭಾಷೆ ಇದೆ. ಡಬ್ ಮಾಡಲು Brief ನಲ್ಲಿ ಭಾಷೆಗಳನ್ನು ಸೇರಿಸಿ.",
  "Only producers and admins can approve spending. You can still see what's waiting here.": "ನಿರ್ಮಾಪಕರು ಮತ್ತು ನಿರ್ವಾಹಕರು ಮಾತ್ರ ಖರ್ಚನ್ನು ಅನುಮೋದಿಸಬಹುದು. ಆದರೂ ಇಲ್ಲಿ ಏನು ಕಾಯುತ್ತಿದೆ ಎಂದು ನೀವು ನೋಡಬಹುದು.",
  "Only the selected shot ({code})": "ಆಯ್ಕೆಮಾಡಿದ Shot ಮಾತ್ರ ({code})",
