  "Pick a project above and click Re-index, then search again.": "ಮೇಲೆ ಪ್ರಾಜೆಕ್ಟ್ ಆರಿಸಿ “ಮರು-ಇಂಡೆಕ್ಸ್” ಕ್ಲಿಕ್ ಮಾಡಿ, ನಂತರ ಮತ್ತೆ ಹುಡುಕಿ.",
