  "Places you create in a project are saved here, so you can reuse them in your next video.": "ಪ್ರಾಜೆಕ್ಟ್‌ನಲ್ಲಿ ನೀವು ರಚಿಸುವ ಸ್ಥಳಗಳು ಇಲ್ಲಿ ಉಳಿಯುತ್ತವೆ, ಹೀಗಾಗಿ ನಿಮ್ಮ ಮುಂದಿನ ವೀಡಿಯೊದಲ್ಲಿ ಅವುಗಳನ್ನು ಮರುಬಳಕೆ ಮಾಡಬಹುದು.",
