  "Plan every scene before shots: what each character wants, what's in the way, what turns, and how to cover it.": "Shots ಗೆ ಮೊದಲು ಪ್ರತಿ Scene ಯೋಜಿಸಿ: ಪ್ರತಿ ಪಾತ್ರಕ್ಕೆ ಏನು ಬೇಕು, ಏನು ಅಡ್ಡಿಯಾಗಿದೆ, ಏನು ತಿರುವು ಪಡೆಯುತ್ತದೆ, ಮತ್ತು ಅದನ್ನು ಹೇಗೆ ಕವರ್ ಮಾಡುವುದು.",
  "Plan scenes": "Scenes ಯೋಜಿಸಿ",
