  "Plan shots, generate keyframes and videos, and pick the best takes. The cost is always shown before anything is generated.": "Shots ಯೋಜಿಸಿ, Keyframes ಮತ್ತು ವೀಡಿಯೊಗಳನ್ನು ರಚಿಸಿ, ಮತ್ತು ಅತ್ಯುತ್ತಮ Takes ಆರಿಸಿ. ಏನನ್ನಾದರೂ ರಚಿಸುವ ಮೊದಲು ವೆಚ್ಚವನ್ನು ಯಾವಾಗಲೂ ತೋರಿಸಲಾಗುತ್ತದೆ.",
  "Plan the shots": "Shots ಯೋಜಿಸಿ",
