  "Talking-clip engines": "ಮಾತನಾಡುವ-ಕ್ಲಿಪ್ ಎಂಜಿನ್‌ಗಳು",
  "Talking-head engines animate the face straight from the recorded line. Best mouth shapes; fewer engines and camera moves.": "ಟಾಕಿಂಗ್-ಹೆಡ್ ಎಂಜಿನ್‌ಗಳು ರೆಕಾರ್ಡ್ ಮಾಡಿದ ಸಾಲಿನಿಂದ ನೇರವಾಗಿ ಮುಖವನ್ನು ಅನಿಮೇಟ್ ಮಾಡುತ್ತವೆ. ಅತ್ಯುತ್ತಮ ಬಾಯಿ ಆಕಾರಗಳು; ಕಡಿಮೆ ಎಂಜಿನ್‌ಗಳು ಮತ್ತು ಕ್ಯಾಮೆರಾ ಚಲನೆಗಳು.",
