  "Used by the preview and for your editors' reference. Pick fonts that support your languages' scripts.": "ಪೂರ್ವವೀಕ್ಷಣೆಯಲ್ಲಿ ಮತ್ತು ನಿಮ್ಮ ಎಡಿಟರ್‌ಗಳ ರೆಫರೆನ್ಸ್‌ಗಾಗಿ ಬಳಸಲಾಗುತ್ತದೆ. ನಿಮ್ಮ ಭಾಷೆಗಳ ಲಿಪಿಗಳನ್ನು ಬೆಂಬಲಿಸುವ ಫಾಂಟ್‌ಗಳನ್ನು ಆರಿಸಿ.",
