  "Used for voice-over lines (explainers, devotional stories, ads). Character voices live in the Bible.": "ವಾಯ್ಸ್-ಓವರ್ ಸಾಲುಗಳಿಗೆ ಬಳಸಲಾಗುತ್ತದೆ (ವಿವರಣಾತ್ಮಕ, ಭಕ್ತಿ ಕಥೆಗಳು, ಜಾಹೀರಾತುಗಳು). ಪಾತ್ರಗಳ ಧ್ವನಿಗಳು Bible ನಲ್ಲಿರುತ್ತವೆ.",
  "Used when a creator has no personal limit. Blank = no limit.": "ಕ್ರಿಯೇಟರ್‌ಗೆ ವೈಯಕ್ತಿಕ ಮಿತಿ ಇಲ್ಲದಿದ್ದಾಗ ಬಳಸಲಾಗುತ್ತದೆ. ಖಾಲಿ = ಮಿತಿ ಇಲ್ಲ.",
