  "What the team has spent on AI services in {month}. Totals reset on the 1st of each month.": "{month} ನಲ್ಲಿ ತಂಡ AI ಸೇವೆಗಳಿಗೆ ಖರ್ಚು ಮಾಡಿದ ಮೊತ್ತ. ಪ್ರತಿ ತಿಂಗಳ 1 ರಂದು ಒಟ್ಟು ಮೊತ್ತ ಮರುಹೊಂದಿಸಲಾಗುತ್ತದೆ.",
  "What will be made": "ಏನು ರಚನೆಯಾಗುತ್ತದೆ",
  "What works": "ಯಾವುದು ಚೆನ್ನಾಗಿದೆ",
  "What's working right now for this audience and platform, from a live web search.": "ಈ ಪ್ರೇಕ್ಷಕರು ಮತ್ತು ಪ್ಲಾಟ್‌ಫಾರ್ಮ್‌ಗೆ ಈಗ ಏನು ಚೆನ್ನಾಗಿ ನಡೆಯುತ್ತಿದೆ — ಲೈವ್ ವೆಬ್ ಹುಡುಕಾಟದಿಂದ.",
  "When": "ಯಾವಾಗ",
  "When a clip's shape differs from the export (e.g. 16:9 → 9:16), crop around the main face instead of the centre.": "ಕ್ಲಿಪ್‌ನ ಆಕಾರ ರಫ್ತಿಗಿಂತ ಭಿನ್ನವಾಗಿದ್ದಾಗ (ಉದಾ. 16:9 → 9:16), ಮಧ್ಯಭಾಗದ ಬದಲು ಮುಖ್ಯ ಮುಖದ ಸುತ್ತ ಕ್ರಾಪ್ ಮಾಡಿ.",
  "When an export finishes we send its details here (for Instagram and other channels). Leave blank to turn off.": "ರಫ್ತು ಮುಗಿದಾಗ ಅದರ ವಿವರಗಳನ್ನು ಇಲ್ಲಿಗೆ ಕಳುಹಿಸುತ್ತೇವೆ (Instagram ಮತ್ತು ಇತರ ಚಾನೆಲ್‌ಗಳಿಗಾಗಿ). ಆಫ್ ಮಾಡಲು ಖಾಲಿ ಬಿಡಿ.",
  "When it's ready, keyframes with this character use the trained face automatically.": "ಸಿದ್ಧವಾದಾಗ, ಈ ಪಾತ್ರವಿರುವ Keyframes ತರಬೇತಿ ಪಡೆದ ಮುಖವನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಬಳಸುತ್ತವೆ.",
  "When someone's work would go over a spending limit, it appears here for a producer or admin to approve.": "ಯಾರದಾದರೂ ಕೆಲಸ ಖರ್ಚಿನ ಮಿತಿ ಮೀರುವಂತಿದ್ದರೆ, ನಿರ್ಮಾಪಕರು ಅಥವಾ ನಿರ್ವಾಹಕರು ಅನುಮೋದಿಸಲು ಅದು ಇಲ್ಲಿ ಕಾಣಿಸುತ್ತದೆ.",
  "When your team starts a project it will show up here.": "ನಿಮ್ಮ ತಂಡ ಪ್ರಾಜೆಕ್ಟ್ ಆರಂಭಿಸಿದಾಗ ಅದು ಇಲ್ಲಿ ಕಾಣಿಸುತ್ತದೆ.",
  "Which AI services are switched on. Only admins can see or change keys.": "ಯಾವ AI ಸೇವೆಗಳು ಆನ್ ಆಗಿವೆ. ನಿರ್ವಾಹಕರು ಮಾತ್ರ ಕೀಗಳನ್ನು ನೋಡಬಹುದು ಅಥವಾ ಬದಲಾಯಿಸಬಹುದು.",
  "Which version you hear (A / B)": "ನೀವು ಕೇಳುವ ಆವೃತ್ತಿ (A / B)",
  "Which voice service speaks each language.": "ಪ್ರತಿ ಭಾಷೆಯನ್ನು ಯಾವ ಧ್ವನಿ ಸೇವೆ ಮಾತನಾಡುತ್ತದೆ.",
  "While the OAuth consent screen is in Testing mode, add the channel owner's Google account as a test user.": "OAuth ಸಮ್ಮತಿ ಪರದೆ Testing ಮೋಡ್‌ನಲ್ಲಿರುವಾಗ, ಚಾನೆಲ್ ಮಾಲೀಕರ Google ಖಾತೆಯನ್ನು ಪರೀಕ್ಷಾ ಬಳಕೆದಾರರಾಗಿ (test user) ಸೇರಿಸಿ.",
  "Who": "ಯಾರು",
  "Who changed what, from where — and the signed consents that cover cloned voices, faces and music.": "ಯಾರು ಏನನ್ನು ಎಲ್ಲಿಂದ ಬದಲಾಯಿಸಿದರು — ಮತ್ತು ಕ್ಲೋನ್ ಮಾಡಿದ ಧ್ವನಿಗಳು, ಮುಖಗಳು ಮತ್ತು ಸಂಗೀತಕ್ಕೆ ಅನ್ವಯಿಸುವ ಸಹಿ ಮಾಡಿದ ಸಮ್ಮತಿಗಳು.",
  "Who works in this studio": "ಈ ಸ್ಟುಡಿಯೋದಲ್ಲಿ ಯಾರು ಕೆಲಸ ಮಾಡುತ್ತಾರೆ",
