  "Works best after scene cards or shots are planned — it compares props, wardrobe and time of day across them.": "Scene ಕಾರ್ಡ್‌ಗಳು ಅಥವಾ Shots ಯೋಜಿಸಿದ ನಂತರ ಇದು ಉತ್ತಮವಾಗಿ ಕೆಲಸ ಮಾಡುತ್ತದೆ — ಅವುಗಳಾದ್ಯಂತ ಪ್ರಾಪ್ಸ್, ವೇಷಭೂಷಣ ಮತ್ತು ದಿನದ ಸಮಯವನ್ನು ಹೋಲಿಸುತ್ತದೆ.",
  "Write 6 hooks, more shocking": "6 ಹುಕ್‌ಗಳನ್ನು ಬರೆಯಿರಿ, ಇನ್ನಷ್ಟು ಆಘಾತಕಾರಿಯಾಗಿ",
